import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { api, ApiError, mutationId, setSession } from './lib/api';
import { loadXlsx } from './lib/xlsx';
import { QuestionBank } from './QuestionBank';
import { StaffOperations } from './StaffOperations';
import { StudentCards } from './StudentCards';
import { StudentExam, StudentResult } from './StudentExam';
import { StudentDashboard, StudentSupportModal } from './StudentDashboard';
import type { Exam } from './StudentDashboard';
import type { ExamResult } from './StudentExam';
import { exportExcel, safeFilename } from './lib/spreadsheet';
import { defaultReportIdentity, escapePrint, letterheadRows, printBaseCss, printLetterhead } from './lib/print-format';
import './styles/cbt-base.css';
import './styles/cbt-dashboard.css';
import './styles/cbt-theme.css';
import './styles/cbt-components.css';
import './styles/cbt-student-mobile.css';
import './arena.css';
import './styles/arena-responsive.css';
import './styles/workspace-polish.css';
import './styles/arena-design-system.css';
import './styles/cbt-parity.css';

type Student = { id: number; nisn: string; nama: string; kelas: string | null; tingkat: string | null };
type Question = { id: number; tipe: string; pertanyaan: string; opsi: { key: string; text: string }[]; poin: number };
type Attempt = { attempt_id: string; exam: { id: number; nama_ujian: string }; expires_at: string; soal: Question[]; jawaban: { question_id: number; answer: string | null; is_flagged: boolean; revision: number }[] };
type Staff = { id: number; nama: string; username?: string; role: string; capabilities?: {teacher:boolean;proctor:boolean} };
type ExamDraft = { id?:number; name:string; grade:string; duration_minutes:number; session_number:number; starts_at:string; ends_at:string; academic_year:string; semester:'ODD'|'EVEN'; subject_name:string; status:'DRAFT'|'ACTIVE'|'INACTIVE'|'ARCHIVED'; target_class_ids:string[]; target_student_ids:number[] };
type UserDraft = {id?:number;role:'ADMIN'|'TEACHER'|'EMPLOYEE';teacher_id:number|null;employee_id:number|null;username:string;name:string;password:string;status:'ACTIVE'|'DISABLED'};

function App() {
  const [student, setStudent] = useState<Student | null>(null);
  const [staff, setStaff] = useState<Staff | null>(null);
  const [sessionLoading,setSessionLoading]=useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [attempt, setAttempt] = useState<Attempt | null>(null);
  const [result, setResult] = useState<ExamResult | null>(null);
  const [resultExamName, setResultExamName] = useState('');
  const [resultExamId, setResultExamId] = useState<number | null>(null);
  const [review, setReview] = useState<{soal:{id:number;pertanyaan?:string;status:string}[]} | null>(null);
  const [reviewLoading, setReviewLoading] = useState(false);
  const [reviewError, setReviewError] = useState('');
  const [examHelpOpen,setExamHelpOpen] = useState(false);
  const [answers, setAnswers] = useState<Record<number, string>>({});
  const [flags, setFlags] = useState<Record<number, boolean>>({});
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const [saveState, setSaveState] = useState<'saved'|'saving'|'error'>('saved');
  const [nisn, setNisn] = useState('');
  const [pin, setPin] = useState('');
  const [showPin, setShowPin] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [staffLoginOpen, setStaffLoginOpen] = useState(false);
  const [loginHelpOpen, setLoginHelpOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(()=>localStorage.getItem('mansapa-cbt-theme-v2')==='dark');
  useEffect(()=>{document.documentElement.dataset.theme=darkMode?'dark':'';localStorage.setItem('mansapa-cbt-theme-v2',darkMode?'dark':'light');},[darkMode]);
  const timers = useRef(new Map<number, number>());
  const retryTimers = useRef(new Map<number, number>());
  const retryAttempts = useRef(new Map<number, number>());
  const pending = useRef(new Map<number, Promise<void>>());
  const latestDraft = useRef(new Map<number, {question:Question;answer:string;flagged:boolean}>());
  const retryDraft = useRef(new Map<number, {question:Question;answer:string;flagged:boolean;mutationId:string}>());
  const revisionState = useRef<Record<number, number>>({});
  const failedSaves = useRef(new Set<number>());
  const submittingAttempt = useRef(false);
  function refreshSaveState() {
    setSaveState(failedSaves.current.size ? 'error' : pending.current.size || timers.current.size ? 'saving' : 'saved');
  }
  function queueSaveRetry(questionId:number){
    if(submittingAttempt.current||retryTimers.current.has(questionId))return;
    const attemptCount=(retryAttempts.current.get(questionId)??0)+1;
    if(attemptCount>5)return;
    retryAttempts.current.set(questionId,attemptCount);
    const base=Math.min(60_000,5_000*2**(attemptCount-1));
    const delay=Math.round(base*(0.8+Math.random()*0.4));
    const timer=window.setTimeout(()=>{retryTimers.current.delete(questionId);const draft=latestDraft.current.get(questionId)??retryDraft.current.get(questionId);if(draft&&!submittingAttempt.current)void save(draft.question,draft.answer,draft.flagged).catch(()=>undefined);},delay);
    retryTimers.current.set(questionId,timer);
  }

  const loadExams = async () => {const rows=await api<Exam[]>('/api/student/exams');setExams(rows);return rows;};
  async function login(event: React.FormEvent) {
    event.preventDefault(); setBusy(true); setMessage('');
    try {
      const result = await api<{ token: string; csrf_token: string; student: Student }>('/api/auth/student/login', { method: 'POST', body: { nisn, pin } });
      localStorage.setItem('arena_active_portal','student');setSession(result.token, result.csrf_token); setStaff(null);setStudent(result.student); await loadExams();
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Login gagal'); }
    finally { setBusy(false); }
  }
  async function staffLogin(event: React.FormEvent) {
    event.preventDefault(); setBusy(true); setMessage('');
    try { const result=await api<{csrf_token:string;staff:Staff}>('/api/auth/staff/login',{method:'POST',body:{username,password}});localStorage.setItem('arena_active_portal','staff');setSession(null,result.csrf_token);setStudent(null);setStaff(result.staff);setStaffLoginOpen(false); }
    catch(error){setMessage(error instanceof Error?error.message:'Login staf gagal');} finally{setBusy(false);}
  }
  async function start(examId: number) {
    setBusy(true); setMessage('');
    try {
      setResult(null); setResultExamId(null); setReview(null); setReviewError(''); setExamHelpOpen(false);
      const result = await api<Attempt>(`/api/student/exams/${examId}/start`, { method: 'POST', body: {} });
      setAttempt(result);
      const savedAnswers: Record<number, string> = {}; const savedRevisions: Record<number, number> = {};
      const savedFlags: Record<number, boolean> = {};
      result.jawaban.forEach((item) => { savedAnswers[item.question_id] = item.answer ?? ''; savedRevisions[item.question_id] = item.revision; savedFlags[item.question_id] = item.is_flagged; });
      revisionState.current = savedRevisions; failedSaves.current.clear(); setSaveState('saved'); setAnswers(savedAnswers); setFlags(savedFlags);
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Tidak dapat membuka ujian'); }
    finally { setBusy(false); }
  }
  async function save(question: Question, value: string, flagged = flags[question.id] ?? false) {
    if (!attempt) return;
    latestDraft.current.set(question.id,{question,answer:value,flagged});
    const existing = pending.current.get(question.id);
    if(existing)return existing;
    const request = (async () => {
      try {
        while(latestDraft.current.has(question.id)){
          const draft=latestDraft.current.get(question.id)!;const retryable=retryDraft.current.get(question.id);const payload=retryable&&retryable.answer===draft.answer&&retryable.flagged===draft.flagged?retryable:{...draft,mutationId:mutationId()};retryDraft.current.set(question.id,payload);latestDraft.current.delete(question.id);setSaveState(failedSaves.current.size?'error':'saving');
          const result=await api<{revision:number}>(`/api/student/exams/${attempt.exam.id}/answers/${question.id}`,{method:'PUT',body:{answer:payload.answer||null,is_flagged:payload.flagged,attempt_id:attempt.attempt_id,base_revision:revisionState.current[question.id]??0,mutation_id:payload.mutationId}});
          revisionState.current={...revisionState.current,[question.id]:result.revision};
          retryDraft.current.delete(question.id);
          failedSaves.current.delete(question.id);
          retryAttempts.current.delete(question.id);
          if (!failedSaves.current.size) setMessage('');
        }
      }catch(error){const pendingDraft=retryDraft.current.get(question.id);const newest=latestDraft.current.get(question.id)??pendingDraft;if(newest){latestDraft.current.set(question.id,newest);failedSaves.current.add(question.id);const retryable=!(error instanceof ApiError)||(error.statusCode>=500||error.statusCode===429);if(retryable)queueSaveRetry(question.id);}else failedSaves.current.add(question.id);setMessage(error instanceof Error?error.message:'Jawaban belum tersimpan');throw error;}
    })();
    pending.current.set(question.id, request);
    try { await request; } finally { if (pending.current.get(question.id) === request) pending.current.delete(question.id); refreshSaveState(); }
  }
  function change(question: Question, value: string) {
    setAnswers((current) => ({ ...current, [question.id]: value }));
    const retry=retryTimers.current.get(question.id);if(retry)window.clearTimeout(retry);retryTimers.current.delete(question.id);retryAttempts.current.delete(question.id);
    const old = timers.current.get(question.id); if (old) window.clearTimeout(old);
    timers.current.set(question.id, window.setTimeout(() => { timers.current.delete(question.id); void save(question, value).catch(() => undefined); }, 350));
    refreshSaveState();
  }
  function toggleFlag(question: Question) {
    const next = !(flags[question.id] ?? false);
    setFlags((current) => ({ ...current, [question.id]: next }));
    const retry=retryTimers.current.get(question.id);if(retry)window.clearTimeout(retry);retryTimers.current.delete(question.id);retryAttempts.current.delete(question.id);
    const old = timers.current.get(question.id); if (old) window.clearTimeout(old);
    timers.current.set(question.id, window.setTimeout(() => { timers.current.delete(question.id); void save(question, answers[question.id] ?? '', next).catch(() => undefined); }, 350));
    refreshSaveState();
  }
  async function retrySave() {
    if (!attempt) return;
    for(const timer of retryTimers.current.values())window.clearTimeout(timer);retryTimers.current.clear();retryAttempts.current.clear();
    await Promise.allSettled([...failedSaves.current].map(questionId => {
      const question = attempt.soal.find(item => item.id === questionId);
      return question ? save(question, answers[questionId] ?? '', flags[questionId] ?? false) : Promise.resolve();
    }));
  }
  async function submit(finalizeOnly = false) {
    if (!attempt) return;
    setBusy(true);submittingAttempt.current=true;
    for(const timer of retryTimers.current.values())window.clearTimeout(timer);retryTimers.current.clear();
    try {
      const due = [...timers.current.entries()];
      due.forEach(([, timer]) => window.clearTimeout(timer)); timers.current.clear();
      if (finalizeOnly) {
        // The API rejects writes after expiry. Finalize the answers already stored
        // even when a late autosave fails, so the student can still see a result.
        await Promise.race([
          Promise.allSettled([...pending.current.values()]),
          new Promise<void>(resolve=>window.setTimeout(resolve,3000)),
        ]);
        latestDraft.current.clear();
      }
      else {
        for (const [questionId] of due) { const question = attempt.soal.find((item) => item.id === questionId); if (question) latestDraft.current.set(questionId,{question,answer:answers[questionId]??'',flagged:flags[questionId]??false}); }
        while(timers.current.size||pending.current.size||latestDraft.current.size){
          for(const[questionId,timer]of timers.current){window.clearTimeout(timer);timers.current.delete(questionId);const question=attempt.soal.find(item=>item.id===questionId);if(question)latestDraft.current.set(questionId,{question,answer:answers[questionId]??'',flagged:flags[questionId]??false});}
          const questionIds=new Set([...pending.current.keys(),...latestDraft.current.keys()]);
          await Promise.all([...questionIds].map(questionId=>{const draft=latestDraft.current.get(questionId);return draft?save(draft.question,draft.answer,draft.flagged):pending.current.get(questionId)!;}));
        }
        if (failedSaves.current.size) throw new Error('Ada jawaban yang belum tersimpan. Coba simpan lagi sebelum mengirim ujian.');
      }
      const completed = await api<ExamResult>(`/api/student/exams/${attempt.exam.id}/submit`, { method: 'POST', body: finalizeOnly ? {finalize_only:true} : {} });
      const actual = await api<ExamResult>(`/api/student/exams/${attempt.exam.id}/result`).catch(() => completed);
      setMessage(''); setResultExamId(attempt.exam.id); setResultExamName(attempt.exam.nama_ujian); setReview(null); setReviewError(''); setResult({...completed,...actual}); setAttempt(null); await loadExams();
    } catch (error) { setMessage(finalizeOnly?'Waktu habis. Hasil belum dapat dimuat; coba lagi saat koneksi tersedia.':error instanceof Error ? error.message : 'Submit gagal'); throw error; }
    finally { submittingAttempt.current=false;setBusy(false); }
  }
  async function showResult(examId:number){setBusy(true);setMessage('');setReview(null);setReviewError('');try{setResultExamId(examId);setResultExamName(exams.find(item=>item.id===examId)?.nama_ujian??'');setResult(await api<ExamResult>(`/api/student/exams/${examId}/result`));}catch(error){setMessage(error instanceof Error?error.message:'Hasil belum tersedia');}finally{setBusy(false);}}
  async function loadReview(){if(resultExamId===null)return;setReviewLoading(true);setReviewError('');try{const data=await api<{soal:{id:number;pertanyaan?:string;status:string}[]}>(`/api/student/exams/${resultExamId}/review`);if(!data.soal?.length)throw new Error('Data soal review belum tersedia. Hubungi petugas ujian.');setReview(data);}catch(error){setReview(null);setReviewError(error instanceof Error?error.message:'Review gagal dimuat');}finally{setReviewLoading(false);}}
  function terminated(hasil:ExamResult|null){setResultExamId(attempt?.exam.id??null);setResultExamName(attempt?.exam.nama_ujian??'');setAttempt(null);setResult(hasil??{status:'TERMINATED'});setReview(null);setReviewError('');setReviewLoading(false);void loadExams();}
  async function logout() { try { await api('/api/auth/logout', { method: 'POST', body: {} }); } catch { /* local logout still clears the in-memory token */ } localStorage.removeItem('arena_active_portal');setSession(null, null); setStudent(null); setStaff(null); setAttempt(null); setResult(null); setExams([]); }
  useEffect(() => {
    let cancelled=false;
    const params=new URLSearchParams(window.location.hash.slice(1));const token=params.get('token'),csrf=params.get('csrf');
    const query=new URLSearchParams(window.location.search);const portalHint=query.get('portal');
    if(portalHint==='staff'||portalHint==='student'){localStorage.setItem('arena_active_portal',portalHint);history.replaceState(null,'',window.location.pathname);}
    if(token&&csrf){localStorage.setItem('arena_active_portal','staff');setSession(token,csrf);history.replaceState(null,'',window.location.pathname);void api<{staff:Staff}>('/api/auth/me').then(data=>{if(!cancelled){setStudent(null);setStaff(data.staff);}}).catch(error=>{if(!cancelled)setMessage(error instanceof Error?error.message:'SSO gagal');}).finally(()=>{if(!cancelled)setSessionLoading(false);});return()=>{cancelled=true;};}
    const restoreStudent=async()=>{const data=await api<{student:Student;csrf_token:string}>('/api/auth/student/session');if(cancelled)return;localStorage.setItem('arena_active_portal','student');setSession(null,data.csrf_token);setStaff(null);setStudent(data.student);try{const available=await loadExams();if(cancelled)return;const active=available.find(exam=>exam.status_attempt==='IN_PROGRESS');if(active)await start(active.id);}catch(error){if(!cancelled)setMessage(error instanceof Error?error.message:'Jadwal ujian gagal dimuat');}};
    const restoreStaff=async()=>{const data=await api<{staff:Staff;csrf_token:string}>('/api/auth/staff/session');if(cancelled)return;localStorage.setItem('arena_active_portal','staff');setSession(null,data.csrf_token);setStudent(null);setStaff(data.staff);};
    const restore=async()=>{const preferred=localStorage.getItem('arena_active_portal');const attempts=preferred==='staff'?[restoreStaff,restoreStudent]:[restoreStudent,restoreStaff];let lastFailure:unknown;for(const attemptSession of attempts){try{await attemptSession();return;}catch(error){if(cancelled)return;lastFailure=error;const status=(error as {statusCode?:number})?.statusCode;if(status!==401&&status!==403)break;}}if(!cancelled){setSession(null,null);localStorage.removeItem('arena_active_portal');const status=(lastFailure as {statusCode?:number})?.statusCode;if(status!==401&&status!==403)setMessage(lastFailure instanceof Error?lastFailure.message:'Sesi gagal dipulihkan. Coba muat ulang.');}};
    void restore().finally(()=>{if(!cancelled)setSessionLoading(false);});
    return()=>{cancelled=true;};
  }, []);
  useEffect(()=>{if(!staff)return;const timer=window.setInterval(()=>{void api<{staff:Staff;csrf_token:string}>('/api/auth/staff/session').then(data=>{setSession(null,data.csrf_token);setStaff(data.staff);}).catch(()=>{setSession(null,null);setStaff(null);setMessage('Sesi berakhir. Silakan masuk kembali.');});},6*60*60*1000);return()=>window.clearInterval(timer);},[staff?.id]);
  useEffect(()=>{const expired=()=>{setSession(null,null);setStaff(null);setStaffLoginOpen(true);setMessage('Sesi pengelola berakhir. Masuk kembali untuk menyimpan perubahan.');};window.addEventListener('arena:staff-session-expired',expired);return()=>window.removeEventListener('arena:staff-session-expired',expired);},[]);
  useEffect(() => () => {timers.current.forEach((timer) => window.clearTimeout(timer));retryTimers.current.forEach((timer)=>window.clearTimeout(timer));}, []);
  useEffect(() => {
    if (!attempt) return;
    let timer = 0;
    const heartbeat = () => {
      void api(`/api/student/exams/${attempt.exam.id}/heartbeat`, { method: 'POST', body: {} }).catch((error) => setMessage(error instanceof Error ? error.message : 'Koneksi ujian terputus'));
      timer = window.setTimeout(heartbeat, 45_000 + Math.floor(Math.random() * 15_000));
    };
    timer = window.setTimeout(heartbeat, 45_000 + Math.floor(Math.random() * 15_000));
    return () => window.clearTimeout(timer);
  }, [attempt]);

  const card: React.CSSProperties = {};
  if(sessionLoading)return <main className="center-wrapper"><div className="auth-card" role="status">Memeriksa sesi…</div></main>;
  return <main className={attempt?'arena-app exam-active':'arena-app'}>
     {!staff&&<header className="topbar public-topbar"><div className="dashboard-home-brand"><img src="/assets/img/logo-man1-palembang.png" alt="Lambang MAN 1 Palembang"/><div><strong>MANSAPA ARENA</strong><span>Area Evaluasi dan Asesmen</span></div></div><div className="public-topbar-actions"><button type="button" className="theme-toggle" aria-label={darkMode?'Aktifkan mode terang':'Aktifkan mode gelap'} aria-pressed={darkMode} onClick={()=>setDarkMode(current=>!current)}>◐</button><a href="/auth/sso/start" className="topbar-guru-link"><i className="fa-solid fa-chalkboard-user"/><span className="hide-on-mobile">Portal Guru</span></a>{student?<button className="btn btn-danger" onClick={() => void logout()}><i className="fa-solid fa-arrow-right-from-bracket"/><span className="hide-on-mobile">Keluar</span></button>:<button className="admin-lock" type="button" aria-label="Login pengelola" title="Login Pengelola" onClick={()=>setStaffLoginOpen(true)}><i className="fa-solid fa-lock"/></button>}</div></header>}
    {message && !attempt && <p role="status" style={{ ...card, background: '#fff8e1' }}>{message}</p>}
    {staff ? <StaffPanel staff={staff} onLogout={()=>void logout()} darkMode={darkMode} onToggleTheme={()=>setDarkMode(current=>!current)} /> : student ? attempt ?
      <StudentExam attempt={attempt} studentName={student.nama} answers={answers} flags={flags} busy={busy} saveState={saveState} message={message} change={change} toggleFlag={toggleFlag} retrySave={retrySave} submit={submit} onTerminated={terminated} onHelp={()=>setExamHelpOpen(true)}>{examHelpOpen&&<StudentSupportModal examId={attempt.exam.id} onClose={()=>setExamHelpOpen(false)}/>}</StudentExam>
      : result ? <><StudentResult onHelp={()=>setExamHelpOpen(true)} examName={resultExamName} result={result} review={review} reviewLoading={reviewLoading} reviewError={reviewError} onReview={loadReview} onClose={()=>{setResult(null);setResultExamId(null);setReview(null);setReviewError('');setReviewLoading(false);setExamHelpOpen(false);}}/>{examHelpOpen&&<StudentSupportModal examId={resultExamId} initialCategory="EXAM_LOCKED" onClose={()=>setExamHelpOpen(false)}/>}</>
      : <StudentDashboard student={student} exams={exams} busy={busy} start={start} showResult={showResult}/>
      : <main className="center-wrapper"><div className="auth-card"><div className="auth-header"><i className="fa-solid fa-user-graduate auth-icon"/><span className="student-eyebrow">MANSAPA ARENA</span><h2>Siap untuk ujian?</h2><p>Masuk dengan nomor peserta dan PIN dari petugas.</p></div>{message&&<p className="arena-notice" role="alert">{message}</p>}<form onSubmit={(event) => void login(event)}><div className="input-group"><label className="ui-label" htmlFor="studentNisn">Nomor Peserta (NISN)</label><div className="input-wrapper"><i className="fa-regular fa-id-badge left-icon"/><input id="studentNisn" className="ui-control" required inputMode="numeric" pattern="[0-9]*" maxLength={20} autoComplete="off" autoCapitalize="off" spellCheck={false} value={nisn} onChange={(event) => setNisn(event.target.value)} placeholder="Masukkan NISN" /></div></div><div className="input-group"><label className="ui-label" htmlFor="studentPin">PIN Ujian (4 Digit)</label><div className="input-wrapper"><i className="fa-solid fa-key left-icon"/><input id="studentPin" className="ui-control" required type={showPin?'text':'password'} inputMode="numeric" pattern="[0-9]*" maxLength={12} autoComplete="one-time-code" autoCapitalize="off" spellCheck={false} value={pin} onChange={(event) => setPin(event.target.value)} placeholder="••••"/><button className="toggle-pw" type="button" aria-label={showPin?'Sembunyikan PIN':'Tampilkan PIN'} onClick={()=>setShowPin(value=>!value)}><i className={`fa-regular ${showPin?'fa-eye-slash':'fa-eye'}`}/></button></div></div><button className="ui-button btn btn-primary student-login-button" disabled={busy}>{busy ? 'Memproses…' : 'Masuk Ujian'} <i className="fa-solid fa-arrow-right"/></button></form><button type="button" className="support-link-button" onClick={()=>setLoginHelpOpen(true)}><i className="fa-solid fa-headset"/> Tidak bisa masuk? Kirim tiket bantuan</button></div></main>}
    {!staff&&staffLoginOpen&&<div className="modal show" role="dialog" aria-modal="true" aria-label="Login pengelola" onMouseDown={(event)=>{if(event.target===event.currentTarget)setStaffLoginOpen(false);}}><div className="modal-content staff-login-modal"><div className="modal-title-row"><h3><i className="fa-solid fa-shield-halved"/>Portal Personel Arena</h3><button aria-label="Tutup dialog" onClick={()=>setStaffLoginOpen(false)}>&times;</button></div><p className="login-help-copy">Gunakan akun lokal atau masuk dengan akun Portal Data guru/pegawai.</p><a className="sso-button arena-sso-button" href="/auth/sso/start"><i className="fa-solid fa-right-to-bracket"/> Masuk dengan Portal Data SSO</a><div className="login-divider"><span>atau akun lokal</span></div><form onSubmit={(event)=>void staffLogin(event)}><div className="input-group"><label className="ui-label" htmlFor="staffUsername">Username</label><div className="input-wrapper"><i className="fa-solid fa-user left-icon"/><input id="staffUsername" required autoComplete="username" value={username} onChange={(event)=>setUsername(event.target.value)} /></div></div><div className="input-group"><label className="ui-label" htmlFor="staffPassword">Password</label><div className="input-wrapper"><i className="fa-solid fa-lock left-icon"/><input id="staffPassword" required type="password" autoComplete="current-password" value={password} onChange={(event)=>setPassword(event.target.value)} /></div></div><div className="modal-actions"><button className="btn btn-primary" disabled={busy}>Masuk ke portal</button></div></form></div></div>}
    {!staff&&loginHelpOpen&&<LoginHelpModal initialNisn={nisn} onClose={()=>setLoginHelpOpen(false)}/>}
  </main>;
}

function LoginHelpModal({initialNisn,onClose}:{initialNisn:string;onClose:()=>void}){
 const[studentNisn,setStudentNisn]=useState(initialNisn),[category,setCategory]=useState('ACCOUNT_ACCESS'),[message,setMessage]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false);
 async function send(event:React.FormEvent){event.preventDefault();setBusy(true);setNotice('');try{await api('/api/student/support-tickets/request',{method:'POST',body:{nisn:studentNisn,category,message}});setNotice('Tiket bantuan terkirim. Petugas akan menindaklanjuti.');setMessage('');}catch(error){setNotice(error instanceof Error?error.message:'Tiket gagal dikirim');}finally{setBusy(false);}}
 return <div className="modal show" role="dialog" aria-modal="true" aria-label="Kirim tiket bantuan" onMouseDown={event=>{if(event.target===event.currentTarget)onClose();}}><div className="modal-content support-ticket-modal"><div className="modal-title-row"><h3><i className="fa-solid fa-headset"/>Bantuan Masuk</h3><button aria-label="Tutup dialog" onClick={onClose}>&times;</button></div><p className="login-help-copy">Isi NISN dan kendala agar petugas dapat membantu akses ujian Anda.</p><form onSubmit={event=>void send(event)}><div className="input-group"><label className="ui-label" htmlFor="helpNisn">NISN</label><div className="input-wrapper"><i className="fa-regular fa-id-badge left-icon"/><input id="helpNisn" required minLength={8} maxLength={20} inputMode="numeric" pattern="[0-9]*" value={studentNisn} onChange={event=>setStudentNisn(event.target.value)} placeholder="Nomor peserta"/></div></div><div className="input-group"><label className="ui-label" htmlFor="helpCategory">Topik bantuan</label><select id="helpCategory" className="ui-control" value={category} onChange={event=>setCategory(event.target.value)}><option value="ACCOUNT_ACCESS">Tidak bisa masuk</option><option value="PIN">Masalah PIN</option><option value="CONNECTION">Koneksi</option><option value="TECHNICAL">Gangguan teknis</option><option value="OTHER">Lainnya</option></select></div><div className="input-group"><label className="ui-label" htmlFor="helpMessage">Kendala</label><textarea id="helpMessage" required minLength={5} maxLength={1000} rows={4} value={message} onChange={event=>setMessage(event.target.value)} placeholder="Jelaskan kendala yang dialami"/></div>{notice&&<p className="arena-notice" role="status">{notice}</p>}<div className="modal-actions"><button type="button" className="btn btn-secondary" onClick={onClose}>Tutup</button><button className="btn btn-primary" disabled={busy}>{busy?'Mengirim…':'Kirim tiket'}</button></div></form></div></div>;
}

