  useEffect(()=>{if(view!=='exams'||!examFormOpen||examTargetSearch.trim().length<2){setExamTargetCandidates([]);return;}let cancelled=false;const timer=window.setTimeout(()=>{const params=new URLSearchParams({page:'1',limit:'30',q:examTargetSearch.trim()});if(examDraft.grade)params.set('grade',examDraft.grade);void api<{items:Array<Record<string,unknown>>}>(`/api/admin/students?${params}`).then(result=>{if(!cancelled)setExamTargetCandidates(result.items);}).catch(error=>{if(!cancelled)setNotice(error instanceof Error?error.message:'Pencarian siswa gagal');});},250);return()=>{cancelled=true;window.clearTimeout(timer);};},[view,examFormOpen,examTargetSearch,examDraft.grade]);
