  const card:React.CSSProperties={border:'1px solid #d9e2ec',borderRadius:12,padding:18,margin:'12px 0',background:'#fff'};
  async function sync(){setBusy(true);try{const result=await api(`/api/admin/portal-data/sync/${syncType}`,{method:'POST',body:{}});setData(result);setNotice('Sinkronisasi selesai');}catch(error){setNotice(error instanceof Error?error.message:'Sinkronisasi gagal');}finally{setBusy(false);}}
  async function resetSelected(){if(!selectedStudents.length){setNotice('Pilih siswa dahulu dari daftar siswa.');return;}setBusy(true);try{const result=await api<{reset:number;failed:number}>('/api/admin/students/reset-batch',{method:'POST',body:{student_ids:selectedStudents,exam_id:Number(examId),reason}});setNotice(`Reset berhasil ${result.reset}; gagal ${result.failed}`);await loadStudents();}catch(error){setNotice(error instanceof Error?error.message:'Reset gagal');}finally{setBusy(false);}}
  async function loadStudents(page=studentPage,q=studentQuery){setBusy(true);setNotice('');try{setStudentPage(page);const params=new URLSearchParams({page:String(page),limit:'50',attempt_status:studentAttemptStatus,sort:studentSort});if(q.trim())params.set('q',q.trim());if(studentGrade)params.set('grade',studentGrade);if(studentClass)params.set('class_id',studentClass);const result=await api<{items:Array<Record<string,unknown>>;page:number;limit:number;total:number}>(`/api/admin/students?${params}`);if(result.items.length){const pins=await api<{items:Array<{student_id:number;pin:string|null}>}>('/api/admin/students/pins',{method:'POST',body:{student_ids:result.items.map(row=>Number(row.id))}});const byId=new Map(pins.items.map(item=>[item.student_id,item.pin]));result.items=result.items.map(row=>({...row,pin:byId.get(Number(row.id))??null}));}setData(result);}catch(error){setNotice(error instanceof Error?error.message:'Data siswa gagal dimuat');}finally{setBusy(false);}}
  async function selectAllFilteredStudents(){setBusy(true);setNotice('Mengambil siswa aktif sesuai filter…');try{const ids:number[]=[];let total=0;for(let page=1;page<=50;page++){const params=new URLSearchParams({page:String(page),limit:'100',attempt_status:studentAttemptStatus,sort:studentSort});if(studentQuery.trim())params.set('q',studentQuery.trim());if(studentGrade)params.set('grade',studentGrade);if(studentClass)params.set('class_id',studentClass);const result=await api<{items:Array<Record<string,unknown>>;total:number}>(`/api/admin/students?${params}`);total=result.total;ids.push(...result.items.filter(row=>row.cbt_status==='ACTIVE').map(row=>Number(row.id)));if(ids.length>=total||result.items.length<100)break;}if(total>5000)throw new Error('Hasil filter lebih dari 5.000 siswa. Saring tingkat atau kelas dahulu.');setSelectedStudents(ids);setNotice(`${ids.length.toLocaleString('id-ID')} siswa aktif dipilih dari ${total.toLocaleString('id-ID')} hasil filter.`);}catch(error){setNotice(error instanceof Error?error.message:'Pemilihan siswa gagal');}finally{setBusy(false);}}
  async function rotatePins(){if(!selectedStudents.length){setNotice('Pilih siswa dahulu dari daftar siswa.');return;}if(!window.confirm(`Terbitkan PIN baru untuk ${selectedStudents.length.toLocaleString('id-ID')} siswa? PIN lama mereka tidak akan berlaku lagi.`))return;setBusy(true);setNotice('Memproses PIN dalam batch maksimal 100 siswa…');setPinCredentials([]);const issued:Array<{student_id:number;nisn:string;name:string;pin:string}>=[];try{for(let offset=0;offset<selectedStudents.length;offset+=100){const chunk=selectedStudents.slice(offset,offset+100);try{const result=await api<{credentials:Array<{student_id:number;nisn:string;name:string;pin:string}>}>('/api/admin/students/pin-batch',{method:'POST',body:{student_ids:chunk}});issued.push(...result.credentials);setPinCredentials([...issued]);setNotice(`PIN diterbitkan untuk ${issued.length.toLocaleString('id-ID')} dari ${selectedStudents.length.toLocaleString('id-ID')} siswa…`);}catch(error){setNotice(`Proses berhenti setelah ${issued.length.toLocaleString('id-ID')} PIN. PIN yang sudah terbit tetap berlaku dan bisa dicetak ulang; batch berikutnya gagal: ${error instanceof Error?error.message:'kesalahan server'}`);return;}}setNotice(`${issued.length.toLocaleString('id-ID')} PIN berhasil diterbitkan. PIN dapat dibuka kembali untuk kontrol siswa atau cetak kartu.`);await loadStudents();}catch(error){setNotice(error instanceof Error?error.message:'Penerbitan PIN gagal');}finally{setBusy(false);}}
  function newUser(){setUserDraft({role:'ADMIN',teacher_id:null,employee_id:null,username:'',name:'',password:'',status:'ACTIVE'});setUserFormOpen(true);}
  function editUser(row:Record<string,unknown>){setUserDraft({id:Number(row.id),role:row.role as UserDraft['role'],teacher_id:row.teacher_id==null?null:Number(row.teacher_id),employee_id:row.employee_id==null?null:Number(row.employee_id),username:String(row.username),name:String(row.name),password:'',status:row.status as UserDraft['status']});setUserFormOpen(true);}
  async function saveUser(event:React.FormEvent){event.preventDefault();setBusy(true);setNotice('');try{await api('/api/admin/users',{method:'POST',body:{...userDraft,password:userDraft.password||undefined}});setUserFormOpen(false);setNotice(userDraft.id?'Akun berhasil diperbarui':'Akun berhasil dibuat');await load('users');const refreshed=await api<typeof personnel>('/api/admin/personnel');setPersonnel(refreshed);}catch(error){setNotice(error instanceof Error?error.message:'Akun gagal disimpan');}finally{setBusy(false);}}
  function downloadUserTemplate(){void exportExcel('template-akun-arena.xlsx',[{name:'Akun',rows:[['username','name','password','role','status','teacher_id','employee_id'],['guru.contoh','Nama Guru','GantiDenganPassword12','TEACHER','ACTIVE',1,'']],widths:[24,32,30,16,16,16,16]},{name:'Petunjuk',rows:[['Kolom','Aturan'],['role','ADMIN, TEACHER, atau EMPLOYEE'],['teacher_id / employee_id','Isi ID personel Arena yang aktif sesuai role; isi salah satu saja. Akun ADMIN membiarkan keduanya kosong.'],['password','Password awal minimal 12 karakter. Ganti contoh sebelum impor.'],['Impor','Semua baris diproses dalam satu transaksi; jika ada baris salah, tidak ada akun yang dibuat.']],widths:[24,105]}]);}
  async function importUserFile(file:File){setBusy(true);setNotice('');try{const library=await loadXlsx();const workbook=library.read(await file.arrayBuffer(),{type:'array'}),sheet=workbook.Sheets[workbook.SheetNames[0]!];if(!sheet)throw new Error('Sheet pertama tidak ditemukan');const matrix=library.utils.sheet_to_json<unknown[]>(sheet,{header:1,defval:'',blankrows:false}),headers=(matrix.shift()??[]).map(value=>String(value).trim().toLowerCase()),rows=matrix.filter(row=>row.some(value=>String(value??'').trim())).map((values,index)=>{const row:Record<string,string>={};headers.forEach((header,column)=>row[header]=String(values[column]??'').trim());const role=({admin:'ADMIN',guru:'TEACHER',teacher:'TEACHER',pegawai:'EMPLOYEE',employee:'EMPLOYEE'} as Record<string,string>)[(row.role??'').toLowerCase()]??(row.role??'').toUpperCase();const optionalId=(value:string|undefined)=>value?Number(value):null;const teacherId=optionalId(row.teacher_id),employeeId=optionalId(row.employee_id);if((teacherId!==null&&!Number.isSafeInteger(teacherId))||(employeeId!==null&&!Number.isSafeInteger(employeeId)))throw new Error(`Baris ${index+2}: ID personel harus berupa angka`);return{username:row.username??'',name:row.name??row.nama_lengkap??'',password:row.password??'',role,status:(row.status??'ACTIVE').toUpperCase(),teacher_id:teacherId,employee_id:employeeId};});if(!rows.length||rows.length>200)throw new Error('Impor harus berisi 1–200 akun');const result=await api<{imported:number}>('/api/admin/users/import',{method:'POST',body:{rows}});setNotice(`${result.imported} akun berhasil diimpor.`);await load('users');}catch(error){setNotice(error instanceof Error?error.message:'Impor akun gagal');}finally{setBusy(false);}}
  function choosePerson(id:string){const list=userDraft.role==='TEACHER'?personnel.teachers:personnel.employees;const person=list.find((item)=>String(item.id)===id);if(!person)return;setUserDraft({...userDraft,teacher_id:userDraft.role==='TEACHER'?Number(person.id):null,employee_id:userDraft.role==='EMPLOYEE'?Number(person.id):null,username:userDraft.username||String(person.nip??''),name:String(person.name)});}
  async function ticketAction(ticket:Record<string,unknown>,status:string){const id=String(ticket.id),note=status==='RESOLVED'?ticketNotes[id]?.trim()??'':'';if(status==='RESOLVED'&&!note){setNotice('Isi catatan penyelesaian untuk siswa.');return;}setBusy(true);try{await api(`/api/staff/support-tickets/${id}/status`,{method:'POST',body:{status,note}});setTicketNotes(previous=>({...previous,[id]:''}));await loadTickets();}catch(error){setNotice(error instanceof Error?error.message:'Update tiket gagal');}finally{setBusy(false);}}
  async function resetTicketAttempt(ticket:Record<string,unknown>){const id=String(ticket.id),reason=ticketReasons[id]?.trim()??'';if(reason.length<3){setNotice('Isi alasan pemulihan sesi minimal 3 karakter.');return;}setBusy(true);setNotice('');try{await api(`/api/staff/support-tickets/${id}/reset`,{method:'POST',body:{reason}});setTicketReasons(previous=>({...previous,[id]:''}));setNotice('Sesi CBT dibuka kembali; jawaban tersimpan dan sisa waktu dipulihkan.');await loadTickets();}catch(error){setNotice(error instanceof Error?error.message:'Sesi CBT gagal direset');}finally{setBusy(false);}}
  async function loadFollowCandidates(){if(!followSource){setNotice('Pilih ujian sumber terlebih dahulu');return;}setBusy(true);setNotice('');setFollowSelected([]);try{const result=await api<{items:Array<Record<string,unknown>>}>(`/api/admin/follow-ups/candidates?source_exam_id=${followSource}&type=${followType}`);setFollowCandidates(result.items);}catch(error){setNotice(error instanceof Error?error.message:'Kandidat gagal dimuat');}finally{setBusy(false);}}
